(() => {
  function clean(t) {
    return String(t ?? '').replace(/\s+/g, ' ').trim();
  }
  const url = location.href;
  const title = document.title;
  const text = clean((document.body && document.body.innerText) || '').slice(0, 4000);

  // table headers
  const headers = [];
  document.querySelectorAll('table thead th, table thead td, [role="columnheader"]').forEach((el) => {
    const t = clean(el.innerText || el.textContent);
    if (t && t.length < 80) headers.push(t);
  });

  // first data table sample cells
  const firstRow = [];
  const tr = document.querySelector('table tbody tr');
  if (tr) {
    tr.querySelectorAll('td, th').forEach((td) => {
      firstRow.push(clean(td.innerText || td.textContent).slice(0, 60));
    });
  }

  // nav / menu labels (seller center)
  const nav = [];
  document.querySelectorAll('nav a, [class*="menu"] a, [class*="Menu"] a, aside a').forEach((a) => {
    const t = clean(a.innerText || a.textContent);
    if (t && t.length < 40 && t.length > 1) nav.push(t);
  });
  const navUniq = [...new Set(nav)].slice(0, 40);

  // metric cards / KPI labels near top
  const kpiCandidates = [];
  document.querySelectorAll('[class*="metric"], [class*="Metric"], [class*="stat"], [class*="Stat"], [class*="card"], [class*="Card"]').forEach((el) => {
    const t = clean(el.innerText || el.textContent);
    if (t && t.length > 2 && t.length < 120) kpiCandidates.push(t);
  });

  // performance resource hints (api paths from performance if any - limited)
  const perf = (performance.getEntriesByType('resource') || [])
    .map((e) => e.name)
    .filter((u) => /api|ads|campaign|report|stat|gmv|order/i.test(u))
    .slice(0, 30);

  return {
    ok: true,
    url,
    title,
    ready: document.readyState,
    textLen: ((document.body && document.body.innerText) || '').length,
    headers: [...new Set(headers)].slice(0, 40),
    firstRow,
    navUniq,
    kpiSample: kpiCandidates.slice(0, 15),
    apiHints: perf,
    textHead: text.slice(0, 1500)
  };
})()

