}

Write-Step "list stores (dynamic)..."
$listRaw = Invoke-Ziniao @('store', 'list', '--format', 'json')
if ($listRaw -match '(?s)\{[\s\S]*"ok"\s*:\s*true[\s\S]*\}') {
  $listRaw = $Matches[0]
}
try {
  $listObj = $listRaw | ConvertFrom-Json
} catch {
