  throw "store list JSON parse failed: $_ | raw=$listRaw"
}
if (-not $listObj.ok) {
  $errMsg = "store list failed: $listRaw"
  $hint = $null
  if ($listRaw -match '9481|Bridge|network|无法连接') {
    $hint = "无法连接紫鸟 Bridge (http://127.0.0.1:9481)。请打开并登录紫鸟桌面客户端后重试。"
    Write-Host ""
