    if (r.spend != null && r.spend !== '') score += 2;
    if (r.roi != null && r.roi !== '') score += 2;
    if (r.revenue != null && r.revenue !== '') score += 2;
    if (r.orders != null && r.orders !== '') score += 1;
  }
