  const TEXT_FIELDS = { campaign: 1, deliveryStatus: 1 };

  function matchHeaderField(headerText) {
    const t = cleanText(headerText).toLowerCase();
    if (!t) return null;
    // 具体列优先，避免「成本」吃掉「净成本/平均下单成本」，「ROI」吃掉「目标 ROI」
    const order = [
      'planStatus',
      'targetRoi',
      'avgOrderCost',
      'netCost',
      'dailyBudget',
      'deliveryStatus',
      'roi',
      'spend',
      'orders',
      'revenue',
      'campaign'
    ];
    for (const field of order) {
      for (const a of HEADER_ALIASES[field]) {
        const al = a.toLowerCase();
        // 禁止短词反包含（否则 t="roi" 会命中 al="目标 roi"）
        const hit =
          t === al ||
          t.includes(al) ||
          (al.length >= 4 && t.length >= 4 && al.includes(t));
        if (!hit) continue;
