/**
 * DOM 表格解析：按表头语义匹配列，抽取广告系列行
 * 避免依赖哈希 class，适配 TikTok Seller / Ads 改版
 */

import { HEADER_ALIASES } from '../lib/constants.js';
import { cleanText, parseNumber } from './normalize.js';

/**
 * 判断表头文本属于哪个业务字段
 * @param {string} headerText
 * @returns {keyof typeof HEADER_ALIASES|null}
 */
export function matchHeaderField(headerText) {
  const t = cleanText(headerText).toLowerCase();
  if (!t) return null;

  // 具体列优先，避免成本/ROI 宽匹配吃掉净成本、目标 ROI 等
  const order = [
    'planStatus',
    'targetRoi',
    'avgOrderCost',
    'netCost',
    'dailyBudget',
    'deliveryStatus',
    'roi',
    'spend',
    'orders',
    'revenue',
    'campaign'
  ];
  for (const field of order) {
    const aliases = HEADER_ALIASES[field];
    if (!aliases) continue;
    for (const a of aliases) {
      const al = a.toLowerCase();
      // 禁止短词反包含（否则 t="roi" 会命中 al="目标 roi"）
      const hit =
        t === al || t.includes(al) || (al.length >= 4 && t.length >= 4 && al.includes(t));
      if (!hit) continue;
      if (field === 'planStatus') {
        if (/投放状态|计划状态|delivery|operation status/.test(t) && !/开关|switch|开\/关/.test(t)) {
          continue;
        }
        if (
          t === al ||
          t === '开关' ||
          t === '开/关' ||
          t === 'switch' ||
          t === 'enable' ||
          t === 'enabled'
        ) {
          return field;
        }
        if (/开关|switch|toggle|on\/off|开\/关/.test(t) && t.length <= 12) return field;
        continue;
      }
      if (field === 'deliveryStatus') {
        if (/开关|switch|toggle|开\/关/.test(t)) continue;
        if (t === '状态' || t === 'status' || /投放状态|计划状态|delivery/.test(t)) return field;
        continue;
      }
      if (field === 'spend') {
        if (/平均下单|cost per|per order|\bcpc\b|\bcpa\b|\bcpm\b|净成本|net cost|预算|budget/.test(t)) {
          continue;
        }
      }
      if (field === 'roi') {
        if (/目标|保护|保障|target|protect|资格/.test(t)) continue;
      }
      if (field === 'dailyBudget') {
        if (/创意|加热|creative|spend|花费|消耗/.test(t) && !/预算|budget/.test(t)) continue;
      }
      if (field === 'campaign' && (al === '名称' || al === 'name')) {
        if (
          !/系列|campaign|广告|活动|product|品名|计划/.test(t) &&
          t !== '名称' &&
          t !== 'name'
        ) {
          continue;
        }
      }
